import React from 'react';

import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import HikingObstaclePhotoAddForm from './HikingObstaclePhotoAddForm';
import HikingObstaclePhotoEditForm from './HikingObstaclePhotoEditForm';
import HikingObstaclePhotoItem from './HikingObstaclePhotoItem';
import { deletePhotoFromHikingObstacle } from '../../@services/hikingObstacles.service';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingObstacleOne, IHikingObstaclePhoto } from '../../@types/hikingObstacles.types';

interface IHikingObstaclePhotosProps {
  oneHikingObstacleData: IHikingObstacleOne;
  hikingData: IHikingData;
  onChangePhotos: (newPhotos: IHikingObstaclePhoto[]) => void;
}

const HikingObstaclePhotos: React.FC<IHikingObstaclePhotosProps> = ({
  oneHikingObstacleData,
  hikingData,
  onChangePhotos,
}) => {
  const handleAddPhoto = () => {
    showModal({
      title: `Добавление фото | ${oneHikingObstacleData.obstacle.name}`,
      size: 'lg',
      style: { minWidth: 600 },
      children: (clos: any) => {
        return (
          <HikingObstaclePhotoAddForm
            hikingObstacle={oneHikingObstacleData}
            hikingData={hikingData}
            callback={(newItem) => {
              clos();
              onChangePhotos([...oneHikingObstacleData.photos, newItem]);
            }}
          />
        );
      },
    });
  };

  const handleEditPhoto = (photo: IHikingObstaclePhoto) => {
    showModal({
      title: 'Редактирование фото',
      style: { minWidth: 600 },
      size: 'lg',
      children: (clos: any) => {
        return (
          <HikingObstaclePhotoEditForm
            photo={photo}
            hikingData={hikingData}
            hikingObstacle={oneHikingObstacleData}
            callback={(newItem) => {
              clos();
              onChangePhotos(
                oneHikingObstacleData.photos.map((p) => (p.id === photo.id ? newItem : p)),
              );
            }}
          />
        );
      },
    });
  };
  const handleDeletePhoto = async (photo: IHikingObstaclePhoto) => {
    if (await confirmModal2(`Удалить фото?`)) {
      await deletePhotoFromHikingObstacle({ id: photo.id, id_hiking: hikingData.id });
      onChangePhotos(oneHikingObstacleData.photos.filter((p) => p.id !== photo.id));
      notificationHelper.success('Удалено');
    }
  };

  return (
    <section>
      <header className="d-flex align-items-center justify-content-between mb-3">
        <h5 className="mb-1">Фотографии</h5>
        <aside>
          <PohButton variant={ButtonVariant.Success} onClick={handleAddPhoto}>
            Добавить
          </PohButton>
        </aside>
      </header>
      {oneHikingObstacleData.photos.length > 0 ? (
        <PohRow className="mb-3">
          {oneHikingObstacleData.photos.map((photo) => {
            return (
              <PohCol sm={6} key={photo.id} className="mb-3">
                <HikingObstaclePhotoItem
                  photo={photo}
                  key={photo.id}
                  toolbar={
                    <div className="d-flex align-items-center">
                      {photo.coordinates && (
                        <a href={`geo:${photo.coordinates.slice(0, 2).join(',')}`}>
                          {photo.coordinates.slice(0, 2).join(', ')}
                        </a>
                      )}
                      <PohButton
                        icon={IconsEnum.edit}
                        className="ms-auto"
                        onClick={() => handleEditPhoto(photo)}
                      />
                      <PohButton icon={IconsEnum.trash} onClick={() => handleDeletePhoto(photo)} />
                    </div>
                  }
                />
              </PohCol>
            );
          })}
        </PohRow>
      ) : (
        <Empty>Нет фоток. Надо добавить</Empty>
      )}
    </section>
  );
};

export default HikingObstaclePhotos;
