import React, { FormEvent } from 'react';

import { getInputDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { addPhotoToHikingObstacle } from '../../@services/hikingObstacles.service';
import { IHikingObstacleOnePhotoAddDTO } from '../../@types/DTO/hikingObstacles.dto.types';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingObstacleOne, IHikingObstaclePhoto } from '../../@types/hikingObstacles.types';

interface IHikingObstaclePhotoAddFormProps {
  hikingObstacle: IHikingObstacleOne;
  hikingData: IHikingData;
  callback: (newPhoto: IHikingObstaclePhoto) => void;
}

const HikingObstaclePhotoAddForm: React.FC<IHikingObstaclePhotoAddFormProps> = ({
  hikingObstacle,
  hikingData,
  callback,
}) => {
  const [data, setData] = React.useState<IHikingObstacleOnePhotoAddDTO>({
    id_hiking: hikingData.id,
    id_hiking_obstacle: hikingObstacle.id,
    lat: '',
    lon: '',
    altitude: '',
    url_preview: '',
    url: '',
    date: '',
    comment: '',
  });

  const [isSaving, setIsSaving] = React.useState(false);

  type T = Pick<
    IHikingObstacleOnePhotoAddDTO,
    'url' | 'url_preview' | 'comment' | 'date' | 'lat' | 'lon' | 'altitude'
  >;

  const handleInputChange = (field: keyof T) => (value: string) => {
    setData((fd) => ({
      ...fd,
      [field]: value,
    }));
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!data.url.length) return notificationHelper.warn('need image');
    try {
      setIsSaving(true);
      const id = await addPhotoToHikingObstacle(data);
      callback({
        id,
        url_preview: data.url,
        url: data.url_preview,
        date: new Date(data.date),
        comment: data.comment,
        created: {
          date: new Date(),
          user: {
            id: 0,
            name: 'X',
            surname: 'X',
            photo: '',
          },
        },
        coordinates: null,
      });

      notificationHelper.success('Добавлено');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ minWidth: 600 }}>
      <PohRow className="mb-2">
        <PohCol sm={2}>Фото</PohCol>
        <PohCol sm={10}>
          <div style={{ overflowY: 'auto', maxHeight: 320 }}>
            <PohImageUploader
              folder={`images/obstacles/${hikingObstacle.obstacle.id}`}
              name={`obstacle_${hikingData.id}`}
              width={800}
              height={600}
              sizes={[255, 800]}
              validation={{ maxHeight: 77777, maxWidth: 75555, size: 250024288 }}
              src={data.url}
              includeExif
              onChange={(src, res, exif) => {
                try {
                  const exifDate =
                    exif!['DateTimeOriginal']?.description ?? exif!['DateCreated'].description;
                  const exifLatitude = exif!['GPSLatitude']?.description;
                  const exifLongitude = exif!['GPSLongitude']?.description;
                  const exifAltitude = exif!['GPSAltitude']?.description;
                  const exifMake = exif!['Make']?.description;
                  const exifModel = exif!['Model']?.description;

                  if (exifDate && exifDate.length) {
                    try {
                      const exifDateStr = exifDate.replace(
                        /^(\d\d\d\d)\D(\d\d?)\D(\d\d?)\D(\d\d)\D(\d\d?)/,
                        '$1-$2-$3T$4:$5',
                      );
                      const ddd = new Date(exifDateStr);
                      handleInputChange('date')(getInputDate(ddd));
                    } catch (error) {
                      console.warn(`Failed to get Exif Date: ${exifDate}`, error);
                    }
                  }

                  if (exifLatitude) {
                    handleInputChange('lat')(exifLatitude.toString());
                  }

                  if (exifLongitude) {
                    handleInputChange('lon')(exifLongitude.toString());
                  }

                  if (exifAltitude) {
                    handleInputChange('altitude')(parseInt(exifAltitude).toString());
                  }

                  if (exifMake && exifMake.length) {
                    handleInputChange('comment')(`${data.comment} ${exifMake} ${exifModel}`);
                  }
                } catch (err) {
                  console.warn(err as Error);
                }

                handleInputChange('url')(src ?? '');
                handleInputChange('url_preview')(res?.sizes?.[255] ?? src ?? '');
              }}
            />
          </div>
        </PohCol>
      </PohRow>
      <PohInput
        required
        disabled={isSaving}
        type={InputTypes.datetimeLocal}
        label="Дата"
        value={data.date}
        onChange={handleInputChange('date')}
        horizontal
        wrapperClassName="mb-3 mt-3"
        min={getInputDate(hikingObstacle.date_in)}
        max={getInputDate(hikingObstacle.date_out)}
        title="Разрешены только фото в диапазоне дат нахождения на точке"
      />
      <PohInput
        type={InputTypes.textarea}
        disabled={isSaving}
        label="Комментарий"
        placeholder="Описание фото"
        horizontal
        wrapperClassName="mb-3"
        value={data.comment}
        onChange={handleInputChange('comment')}
      />
      <PohRow className="mb-3">
        <PohCol sm={2}>Координаты</PohCol>
        <PohCol sm={3}>
          <PohInput
            disabled={isSaving}
            value={data.lat}
            onChange={handleInputChange('lat')}
            placeholder="Lat. Необязательно"
            size={InputSizes.Small}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            disabled={isSaving}
            value={data.lon}
            onChange={handleInputChange('lon')}
            placeholder="Lon. Необязательно"
            size={InputSizes.Small}
          />
        </PohCol>
        <PohCol sm={3}>
          <PohInput
            disabled={isSaving}
            value={data.altitude}
            onChange={handleInputChange('altitude')}
            placeholder="Alt. Необязательно"
            size={InputSizes.Small}
          />
        </PohCol>
      </PohRow>

      <footer className="border-top p-3 text-end">
        <PohButton type="submit" disabled={isSaving}>
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export default HikingObstaclePhotoAddForm;
